def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    original = {(r,c): grid[r][c] for r in range(h) for c in range(w) if grid[r][c] in (1,6)}
    # Each 6 marker projects both diagonal lines across the canvas.
    for (r,c), color in original.items():
        if color != 6:
            continue
        for dc in (-1,1):
            rr, cc = r, c
            while 0 <= rr-1 < h and 0 <= cc-dc < w:
                rr -= 1
                cc -= dc
            while 0 <= rr < h and 0 <= cc < w:
                if (rr,cc) not in original:
                    out[rr][cc] = 6
                rr += 1
                cc += dc
    # The two 1 markers are joined by their diagonal segment; original marks stay intact.
    ones = [(r,c) for (r,c),v in original.items() if v == 1]
    if len(ones) == 2:
        (r1,c1),(r2,c2) = ones
        dr, dc = r2-r1, c2-c1
        g = gcd(abs(dr),abs(dc))
        if g and abs(dr) == abs(dc):
            sr, sc = dr//g, dc//g
            for k in range(g+1):
                p=(r1+k*sr,c1+k*sc)
                if p not in original:
                    out[p[0]][p[1]]=1
    return out
