def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    ones = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    # Diagonal 1-markers delimit a segment. Its cells remain 1 except original markers.
    segments = []
    for i, (r1,c1) in enumerate(ones):
        for r2,c2 in ones[i+1:]:
            dr, dc = r2-r1, c2-c1
            if abs(dr) == abs(dc) and dr != 0:
                sr, sc = dr//abs(dr), dc//abs(dc)
                n = abs(dr)
                cells = [(r1+k*sr,c1+k*sc) for k in range(n+1)]
                segments.append((cells, sr, sc))
                for r,c in cells:
                    if grid[r][c] != 6:
                        out[r][c] = 1
    # A 6 lying on a 1-segment casts a full diagonal perpendicular to that segment.
    for cells, sr, sc in segments:
        cellset = set(cells)
        for r,c in sixes:
            if (r,c) not in cellset:
                continue
            dr, dc = sr, -sc
            rr,cc = r,c
            while 0 <= rr-dr < h and 0 <= cc-dc < w:
                rr -= dr; cc -= dc
            while 0 <= rr < h and 0 <= cc < w:
                if grid[rr][cc] == 4 or grid[rr][cc] == 5 or grid[rr][cc] == 8:
                    out[rr][cc] = 6
                rr += dr; cc += dc
    return out
